{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C12"],
      "claim": "Brigatinib, a close analogue sharing the piperazine-anilinopyrimidine motif, had absolute oral bioavailability of 77% in healthy volunteers in the fed state, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "The same brigatinib analogue in the fasted state had absolute oral bioavailability of 57%, showing high F is not food-dependent and supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "The most structurally similar retrieved analogue had oral bioavailability of approximately 20–25%, at or above the 20% threshold, supporting high F but with a narrower margin.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Brepocitinib, a small-molecule kinase inhibitor with heteroaromatic amine features, had absolute oral bioavailability of 75% in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Imatinib, an oral kinase inhibitor with piperazine and aminopyrimidine features, had mean absolute oral bioavailability of 98%, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Niraparib had absolute oral bioavailability of approximately 73% in patients, supporting high F for a structurally related oral drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Risdiplam has high oral bioavailability with complete absorption and negligible first-pass effects, supporting high F for the query.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Consistent human absolute bioavailability data from structurally related kinase inhibitors with piperazine-anilinopyrimidine motifs (F 57–98%, plus a closest analogue at 20–25%) outweigh the uncertain physicochemical prior. The query is therefore predicted to have oral bioavailability ≥20%.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability measurement for the query molecule was provided.",
    "The closest structural analogue has F near the 20% threshold, adding some uncertainty.",
    "The physicochemical prior suggests poor passive absorption, but no experimental permeability or transporter data for the query are available.",
    "Most analogues have low-to-moderate Morgan similarity (<0.38), so structural transferability is inferential."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

